import React from 'react';
import styled from 'styled-components';

const HomeWrapper = styled.div`
  padding: 2rem;
  text-align: center;
  background: #fdfbfb;
  min-height: 80vh;
`;

const Title = styled.h2`
  color: #444;
  margin-bottom: 1rem;
`;

const Subtitle = styled.p`
  color: #666;
  font-size: 1.2rem;
`;

const Home = () => (
    <HomeWrapper>
        <Title>Добро пожаловать в Zoo Shop 🐾</Title>
        <Subtitle>
            Управляйте продуктами, поставщиками, закупками и изменениями цен в удобном интерфейсе.
        </Subtitle>
    </HomeWrapper>
);

export default Home;
